/**
 * QuizLens AI - Question Detector
 * Accurately detects and parses multiple question types:
 * - Standard Multiple Choice with letters (A, B, C, D, E, F...)
 * - Binary Questions (2 options: Đúng/Sai, True/False, Có/Không, Yes/No)
 * - Multi-select Questions (Tick box, Checkbox, "Chọn các đáp án đúng")
 * - Fill-in-the-blank Questions (..., ___, [...], (...), "Điền vào chỗ trống")
 * - Numbered Options (1, 2, 3, 4)
 * - Roman Numeral Options (I, II, III, IV)
 * - Bullet / Dash / Checkbox marked options (-, •, *, [ ], ☑, ☐)
 * - Unlabeled plain-line options (each line is an option)
 * - Open-ended fill-in-the-blank (without predefined options)
 */

import { QuestionData, QuestionOptions, QuestionType } from '../shared/types';
import { extractOptionsFromDOM } from './dom-extractor';

export interface DetectionResult {
  isValid: boolean;
  data: QuestionData | null;
  reason?: string;
}

const OPTION_LETTERS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'] as const;

/**
 * Regex patterns to detect option letter prefixes:
 * - A. or a.
 * - A) or a)
 * - (A) or (a)
 * - [A] or [a]
 * - A: or a:
 * - A - or a -
 * - A/ or a/
 */
const OPTION_PREFIX_REGEX = /(?:^|[\r\n]+|[•\*\-\–\—\+·▪▫]\s*|\s{2,}|\t)(?:[\(\[]?([A-Ha-h])[\)\].:\-\/]\s*)|(?:\s+)([A-Ha-h])[\.:\-\/]\s*/g;

/**
 * Normalizes text: cleans excessive whitespace while preserving line breaks
 */
export function normalizeText(text: string): string {
  if (!text) return '';
  return text
    .replace(/\u00a0/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

/**
 * Disqualifies navigation headers, menus, or footer noise
 */
function isDisqualifiedNonQuestion(text: string): boolean {
  const trimmed = text.trim();
  if (trimmed.length < 5) return true;

  const noisePatterns = [
    /^(menu|navigation|trang chủ|home|contact|giới thiệu|about us|footer|bản quyền|copyright)/i,
    /^(điều khoản|chính sách bảo mật|terms of service|privacy policy)/i,
    /^(đăng nhập|đăng ký|sign in|sign up|log in|register)$/i
  ];

  return noisePatterns.some((pattern) => pattern.test(trimmed));
}

/**
 * Detects the specific question type based on text content and option characteristics
 */
export function detectQuestionType(text: string, optionsCount = 0): QuestionType {
  const lower = text.toLowerCase();

  // 1. Multi-select cues (Chọn nhiều đáp án đúng, Tick các đáp án, Checkbox)
  const multiSelectRegex = /(?:chọn\s+(?:các|những|nhiều|tất\s+cả|hai|ba|bốn|\d+)\s+(?:đáp\s+án|phương\s+án|câu|khẳng\s+định|ý)|các\s+(?:đáp\s+án|khẳng\s+định|phương\s+án)\s+(?:nào\s+)?đúng|select\s+all(?:\s+that\s+apply)?|choose\s+all|which\s+of\s+the\s+following\s+are\s+correct|những\s+câu\s+nào\s+sau\s+đây\s+đúng|tick\s+vào|chọn\s+các|đánh\s+dấu\s+vào)/i;
  if (multiSelectRegex.test(lower) || /[☑☐]|\bcheckbox\b/i.test(text)) {
    return 'MULTI_SELECT';
  }

  // 2. Fill-in-the-blank cues (..., ___, [...], (...), Điền từ vào chỗ trống)
  const blankRegex = /(?:\.{3,}|_{2,}|…|\[\s*(?:\.{2,}|_{2,}|…|\s*)\s*\]|\(\s*(?:\.{2,}|_{2,}|…|\s*)\s*\)|điền\s+(?:từ|vào\s+chỗ\s+trống|vào\s+ô\s+trống|khuyết)|chọn\s+từ\s+thích\s+hợp|fill\s+in\s+the\s+blank|complete\s+the\s+sentence|missing\s+word)/i;
  if (blankRegex.test(text)) {
    return 'FILL_IN_BLANK';
  }

  // 3. Binary cues (2 options: Đúng/Sai, True/False, Yes/No, Có/Không)
  if (optionsCount === 2) {
    if (/(?:đúng|sai|true|false|yes|no|có|không)/i.test(lower)) {
      return 'BINARY';
    }
  }

  return 'MULTIPLE_CHOICE';
}

/**
 * Strategy 1: Standard Letter Options (A, B, C, D, E, F...)
 */
function tryParseLetterOptions(text: string): QuestionData | null {
  const matches: Array<{ letter: string; index: number; fullMatchLength: number }> = [];
  const regex = new RegExp(OPTION_PREFIX_REGEX);
  let match: RegExpExecArray | null;

  while ((match = regex.exec(text)) !== null) {
    const rawLetter = match[1] || match[2];
    if (!rawLetter) continue;
    const letter = rawLetter.toUpperCase();
    const matchStart = match.index + (match[0].length - match[0].trimStart().length);
    matches.push({
      letter,
      index: matchStart,
      fullMatchLength: match[0].trimStart().length
    });
  }

  if (matches.length < 2) return null;

  // Deduplicate matches: keep the latest appearance of each letter
  const lastSeenIndexByLetter = new Map<string, number>();
  for (let i = 0; i < matches.length; i++) {
    lastSeenIndexByLetter.set(matches[i].letter, i);
  }
  const filteredIndices = new Set(lastSeenIndexByLetter.values());
  const validMatches = matches.filter((_, idx) => filteredIndices.has(idx));

  // Must contain at least A and B
  const uniqueLetters = new Set(validMatches.map((m) => m.letter));
  if (!uniqueLetters.has('A') || !uniqueLetters.has('B')) {
    return null;
  }

  const firstOptionIndex = validMatches[0].index;
  const questionPart = text.slice(0, firstOptionIndex).trim();
  if (questionPart.length < 3) return null;

  const optionsMap: QuestionOptions = {};
  for (let i = 0; i < validMatches.length; i++) {
    const current = validMatches[i];
    const next = validMatches[i + 1];
    const startIndex = current.index + current.fullMatchLength;
    const endIndex = next ? next.index : text.length;

    const content = text.slice(startIndex, endIndex).trim();
    if (!content) return null;

    optionsMap[current.letter] = content;
  }

  if (!optionsMap.A || !optionsMap.B) return null;

  const optionsCount = Object.keys(optionsMap).length;
  const questionType = detectQuestionType(text, optionsCount);

  return {
    question: questionPart,
    options: optionsMap,
    questionType,
    rawText: text
  };
}

/**
 * Strategy 2: Binary Questions without Letter Markers
 * e.g. "Phong cách lãnh đạo dân chủ luôn mang lại hiệu quả: Đúng / Sai"
 * or lines:
 * "Nước sôi ở 100 độ C"
 * "Đúng"
 * "Sai"
 */
function tryParseBinaryOptions(text: string): QuestionData | null {
  // Pattern 2a: Standalone lines of True/False, Đúng/Sai, Có/Không, Yes/No
  const lines = text.split('\n').map((l) => l.trim()).filter((l) => l.length > 0);
  if (lines.length >= 2) {
    const last1 = lines[lines.length - 1];
    const last2 = lines[lines.length - 2];

    const isBinaryPair = (a: string, b: string): [string, string] | null => {
      const cleanA = a.replace(/^[\(\[\-•\*\d+\.\]\s]+/, '').trim().toLowerCase();
      const cleanB = b.replace(/^[\(\[\-•\*\d+\.\]\s]+/, '').trim().toLowerCase();

      if ((cleanA === 'đúng' && cleanB === 'sai') || (cleanA === 'sai' && cleanB === 'đúng')) return ['Đúng', 'Sai'];
      if ((cleanA === 'true' && cleanB === 'false') || (cleanA === 'false' && cleanB === 'true')) return ['True', 'False'];
      if ((cleanA === 'yes' && cleanB === 'no') || (cleanA === 'no' && cleanB === 'yes')) return ['Yes', 'No'];
      if ((cleanA === 'có' && cleanB === 'không') || (cleanA === 'không' && cleanB === 'có')) return ['Có', 'Không'];
      return null;
    };

    const pair = isBinaryPair(last2, last1);
    if (pair) {
      const questionPart = lines.slice(0, lines.length - 2).join('\n').trim();
      if (questionPart.length >= 3) {
        return {
          question: questionPart,
          options: { A: pair[0], B: pair[1] },
          questionType: 'BINARY',
          rawText: text
        };
      }
    }
  }

  // Pattern 2b: Inline binary choices like "Đúng / Sai" or "[ ] Đúng   [ ] Sai"
  const inlineBinaryRegex = /(.*?)(?:[\:\?\-—\n]\s*)?(?:\[\s*\]|\(s*\)|\🔘|\⚪)?\s*(đúng|true|yes|có)\s*(?:\/|\||\\|\s{2,}|\svà\s|\shoặc\s)\s*(?:\[\s*\]|\(s*\)|\🔘|\⚪)?\s*(sai|false|no|không)\s*$/i;
  const inlineMatch = text.match(inlineBinaryRegex);
  if (inlineMatch && inlineMatch[1]?.trim().length >= 3) {
    const questionPart = inlineMatch[1].trim();
    const optA = inlineMatch[2].trim();
    const optB = inlineMatch[3].trim();
    return {
      question: questionPart,
      options: {
        A: optA.charAt(0).toUpperCase() + optA.slice(1).toLowerCase(),
        B: optB.charAt(0).toUpperCase() + optB.slice(1).toLowerCase()
      },
      questionType: 'BINARY',
      rawText: text
    };
  }

  return null;
}

/**
 * Strategy 3: Numbered Options (1., 2., 3., 4.)
 */
function tryParseNumberedOptions(text: string): QuestionData | null {
  const lines = text.split('\n').map((l) => l.trim()).filter((l) => l.length > 0);
  if (lines.length < 3) return null;

  const numberedRegex = /^[\(\[]?([1-8])[\)\].:\-\s]\s*(.+)$/;
  let firstNumberedIdx = -1;
  const numbersFound: Array<{ num: number; content: string }> = [];

  for (let i = 0; i < lines.length; i++) {
    const match = lines[i].match(numberedRegex);
    if (match) {
      const num = parseInt(match[1], 10);
      if (firstNumberedIdx === -1 && num === 1 && i > 0) {
        firstNumberedIdx = i;
      }
      if (firstNumberedIdx !== -1) {
        numbersFound.push({ num, content: match[2].trim() });
      }
    } else if (firstNumberedIdx !== -1) {
      // Multiline content for previous option
      if (numbersFound.length > 0) {
        numbersFound[numbersFound.length - 1].content += `\n${lines[i]}`;
      }
    }
  }

  // Need at least options 1 and 2 in order
  if (numbersFound.length >= 2 && numbersFound[0].num === 1 && numbersFound[1].num === 2) {
    const questionPart = lines.slice(0, firstNumberedIdx).join('\n').trim();
    if (questionPart.length >= 3) {
      const optionsMap: QuestionOptions = {};
      for (let i = 0; i < numbersFound.length && i < OPTION_LETTERS.length; i++) {
        optionsMap[OPTION_LETTERS[i]] = numbersFound[i].content;
      }
      return {
        question: questionPart,
        options: optionsMap,
        questionType: detectQuestionType(text, numbersFound.length),
        rawText: text
      };
    }
  }

  return null;
}

/**
 * Strategy 4: Roman Numeral Options (I, II, III, IV)
 */
function tryParseRomanOptions(text: string): QuestionData | null {
  const lines = text.split('\n').map((l) => l.trim()).filter((l) => l.length > 0);
  if (lines.length < 3) return null;

  const romanRegex = /^[\(\[]?(I|II|III|IV|V|VI)[\)\].:\-\s]\s*(.+)$/i;
  const romanMap: Record<string, number> = { i: 1, ii: 2, iii: 3, iv: 4, v: 5, vi: 6 };
  let firstRomanIdx = -1;
  const romansFound: Array<{ val: number; content: string }> = [];

  for (let i = 0; i < lines.length; i++) {
    const match = lines[i].match(romanRegex);
    if (match) {
      const val = romanMap[match[1].toLowerCase()];
      if (val) {
        if (firstRomanIdx === -1 && val === 1 && i > 0) {
          firstRomanIdx = i;
        }
        if (firstRomanIdx !== -1) {
          romansFound.push({ val, content: match[2].trim() });
        }
      }
    }
  }

  if (romansFound.length >= 2 && romansFound[0].val === 1 && romansFound[1].val === 2) {
    const questionPart = lines.slice(0, firstRomanIdx).join('\n').trim();
    if (questionPart.length >= 3) {
      const optionsMap: QuestionOptions = {};
      for (let i = 0; i < romansFound.length && i < OPTION_LETTERS.length; i++) {
        optionsMap[OPTION_LETTERS[i]] = romansFound[i].content;
      }
      return {
        question: questionPart,
        options: optionsMap,
        questionType: detectQuestionType(text, romansFound.length),
        rawText: text
      };
    }
  }

  return null;
}

/**
 * Strategy 5: Bullet, Dash, or Checkbox Options
 * (- Option, • Option, * Option, [ ] Option, ☑ Option, ☐ Option)
 */
function tryParseBulletOptions(text: string): QuestionData | null {
  const lines = text.split('\n').map((l) => l.trim()).filter((l) => l.length > 0);
  if (lines.length < 3) return null;

  const bulletRegex = /^([•\*\-\–\—\+▪▫☑☐🔘⚪]|\[[\sxX]?\])\s+(.+)$/;
  let firstBulletIdx = -1;
  const bulletsFound: string[] = [];
  let isCheckbox = false;

  for (let i = 0; i < lines.length; i++) {
    const match = lines[i].match(bulletRegex);
    if (match) {
      if (firstBulletIdx === -1 && i > 0) {
        firstBulletIdx = i;
      }
      if (firstBulletIdx !== -1) {
        if (/[☑☐]|\s*\[[\sxX]?\]/.test(match[1])) {
          isCheckbox = true;
        }
        bulletsFound.push(match[2].trim());
      }
    } else if (firstBulletIdx !== -1) {
      if (bulletsFound.length > 0) {
        bulletsFound[bulletsFound.length - 1] += `\n${lines[i]}`;
      }
    }
  }

  if (bulletsFound.length >= 2 && firstBulletIdx > 0) {
    const questionPart = lines.slice(0, firstBulletIdx).join('\n').trim();
    if (questionPart.length >= 3) {
      const optionsMap: QuestionOptions = {};
      for (let i = 0; i < bulletsFound.length && i < OPTION_LETTERS.length; i++) {
        optionsMap[OPTION_LETTERS[i]] = bulletsFound[i];
      }
      const inferredType = isCheckbox ? 'MULTI_SELECT' : detectQuestionType(text, bulletsFound.length);
      return {
        question: questionPart,
        options: optionsMap,
        questionType: inferredType,
        rawText: text
      };
    }
  }

  return null;
}

/**
 * Strategy 6: Plain Unlabeled Lines (Each subsequent line is an option)
 * Useful when copying clean text without prefixes:
 * "Thủ đô của nước Pháp là gì?"
 * "London"
 * "Paris"
 * "Berlin"
 * "Madrid"
 */
function tryParsePlainLineOptions(text: string): QuestionData | null {
  const lines = text.split('\n').map((l) => l.trim()).filter((l) => l.length > 0);
  // Need 1 question line + 2 to 6 candidate option lines
  if (lines.length < 3 || lines.length > 8) return null;

  const firstLine = lines[0];
  const candidateOptions = lines.slice(1);

  // First line MUST look like an actual question or directive
  const isQuestionLike =
    /[?:]$/.test(firstLine) ||
    /^(câu\s+\d+|bài\s+\d+|question\s+\d+|đâu\s+là|ai\s+là|khi\s+nào|tại\s+sao|như\s+thế\s+nào|cái\s+gì|hãy\s+cho\s+biết|chọn|tìm|hãy|cho|tính|xác\s+định|trong\s+các|which|what|where|when|why|how|who)/i.test(firstLine);

  if (!isQuestionLike) return null;

  // Verify all options are reasonably sized (< 200 chars) and not duplicate questions
  const optionsValid = candidateOptions.every((opt) => opt.length > 0 && opt.length < 250 && !opt.endsWith('?'));
  if (!optionsValid) return null;

  const optionsMap: QuestionOptions = {};
  for (let i = 0; i < candidateOptions.length && i < OPTION_LETTERS.length; i++) {
    optionsMap[OPTION_LETTERS[i]] = candidateOptions[i];
  }

  return {
    question: firstLine,
    options: optionsMap,
    questionType: detectQuestionType(text, candidateOptions.length),
    rawText: text
  };
}

/**
 * Strategy 7: Fill-in-the-blank without options (Tự luận / Điền từ khuyết trực tiếp)
 * e.g. "Quang hợp ở thực vật chủ yếu diễn ra ở bào quan ................"
 */
function tryParseFillInTheBlankWithoutOptions(text: string): QuestionData | null {
  const hasBlank = /(?:\.{3,}|_{2,}|…|\[\s*(?:\.{2,}|_{2,}|…|\s*)\s*\]|\(\s*(?:\.{2,}|_{2,}|…|\s*)\s*\))/i.test(text);
  const hasKeyword = /(?:điền\s+(?:vào\s+chỗ\s+trống|vào\s+ô\s+trống|từ|khuyết)|chọn\s+từ\s+thích\s+hợp|fill\s+in\s+the\s+blank|complete\s+the\s+sentence)/i.test(text);

  if ((hasBlank || hasKeyword) && text.trim().length >= 10) {
    return {
      question: text.trim(),
      options: {},
      questionType: 'FILL_IN_BLANK',
      rawText: text
    };
  }

  return null;
}

/**
 * Strategy 8: Direct Question without Options
 * For cases where user highlights only a question (no multiple-choice options provided):
 * e.g.
 * - "Thủ đô của nước Cộng hòa Xã hội Chủ nghĩa Việt Nam hiện nay là thành phố nào?"
 * - "Question 2: What is the primary gas found in Earth's atmosphere?"
 * - "Kết quả của console.log(typeof null) là gì?"
 * - "Cho tam giác vuông có hai cạnh góc vuông là 3cm và 4cm. Tính cạnh huyền?"
 * - "12 * 15 = ?"
 */
export function isDirectQuestion(text: string): boolean {
  const trimmed = text.trim();
  if (trimmed.length < 6 || trimmed.length > 800) return false;
  if (isDisqualifiedNonQuestion(trimmed)) return false;

  // 1. Question prefixes (Câu 1:, Question 2:, Bài 3...)
  const prefixRegex = /^(?:câu|bài|question|task|câu\s+hỏi)\s*\d*[\.:\-]/i;
  if (prefixRegex.test(trimmed)) return true;

  // 2. Ends with a question mark
  if (/[?？]$/.test(trimmed)) return true;

  // 3. Question interrogative patterns in Vietnamese (là gì, bao nhiêu, ở đâu, khi nào...)
  const viQuestionEndings = /(?:là\s+gì|như\s+thế\s+nào|bao\s+nhiêu|ở\s+đâu|khi\s+nào|mấy|nào|sao|đúng\s+không|phải\s+không)\s*[?\.:!]*$/i;
  if (viQuestionEndings.test(trimmed)) return true;

  // 4. Vietnamese question starters
  const viStarters = /^(?:đâu\s+là|ai\s+là|khi\s+nào|tại\s+sao|như\s+thế\s+nào|cái\s+gì|hãy\s+cho\s+biết|hãy\s+tính|hãy\s+tìm|tính\s+|tìm\s+|giải\s+|xác\s+định\s+|cho\s+biết\s+|thủ\s+đô\s+|năm\s+nào|tác\s+giả\s+|nguyên\s+nhân\s+|kết\s+quả\s+|đoạn\s+mã|ý\s+nghĩa\s+của|cho\s+tam\s+giác|phương\s+trình)/i;
  if (viStarters.test(trimmed)) return true;

  // 5. English question starters
  const enStarters = /^(?:what|which|where|when|why|how|who|whom|whose|can|could|would|should|is|are|do|does|did|calculate|find|determine|explain|evaluate|define)\b/i;
  if (enStarters.test(trimmed)) return true;

  // 6. Math formulas ending in = or ?
  if (/[\d\w\)]\s*=\s*[?\.\s]*$/.test(trimmed)) return true;

  return false;
}

/**
 * Parses selected text into structured QuestionData across multiple detection strategies
 */
export function parseQuestionFromText(rawText: string): QuestionData | null {
  const text = normalizeText(rawText);
  if (!text || isDisqualifiedNonQuestion(text)) {
    return null;
  }

  // 1. Try Letter options (A, B, C, D...)
  const letterResult = tryParseLetterOptions(text);
  if (letterResult) return letterResult;

  // 2. Try Binary options (Đúng/Sai, True/False, Có/Không)
  const binaryResult = tryParseBinaryOptions(text);
  if (binaryResult) return binaryResult;

  // 3. Try Numbered options (1., 2., 3., 4.)
  const numberedResult = tryParseNumberedOptions(text);
  if (numberedResult) return numberedResult;

  // 4. Try Roman numeral options (I, II, III, IV)
  const romanResult = tryParseRomanOptions(text);
  if (romanResult) return romanResult;

  // 5. Try Bullet / Checkbox options (-, •, *, [ ], ☑)
  const bulletResult = tryParseBulletOptions(text);
  if (bulletResult) return bulletResult;

  // 6. Try Plain lines (each line is an option)
  const plainResult = tryParsePlainLineOptions(text);
  if (plainResult) return plainResult;

  // 7. Try Open fill-in-the-blank without options
  const fillBlankResult = tryParseFillInTheBlankWithoutOptions(text);
  if (fillBlankResult) return fillBlankResult;

  return null;
}

/**
 * Main detection entry point.
 * 1. Checks if selected text contains question + options.
 * 2. If not, inspects DOM context around selection to find nearby options.
 * 3. If no options anywhere, checks if text itself is a direct question (Short Answer).
 */
export function detectQuestion(
  selectionText: string,
  selectionRange?: Range | null
): DetectionResult {
  const normalized = normalizeText(selectionText);

  if (!normalized || normalized.length < 4) {
    return { isValid: false, data: null, reason: 'Selection text too short' };
  }

  // Step 1: Direct text parsing
  const directResult = parseQuestionFromText(normalized);
  if (directResult) {
    return {
      isValid: true,
      data: directResult
    };
  }

  // Step 2: DOM context extraction if selection range is present
  if (selectionRange) {
    const domExtracted = extractOptionsFromDOM(normalized, selectionRange);
    if (domExtracted) {
      return {
        isValid: true,
        data: domExtracted
      };
    }
  }

  // Step 3: Standalone Direct Question without options (Không cần đáp án / Trả lời ngắn gọn)
  if (isDirectQuestion(normalized)) {
    return {
      isValid: true,
      data: {
        question: normalized,
        options: {},
        questionType: 'SHORT_ANSWER',
        rawText: normalized
      }
    };
  }

  return {
    isValid: false,
    data: null,
    reason: 'Không tìm thấy các phương án hoặc mẫu câu hỏi hợp lệ'
  };
}
