/**
 * QuizLens AI - Result Popup Component
 * Minimalist, clean in-page floating widget positioned near selected text
 */

import { AnswerResult } from '../shared/types';

export class ResultPopup {
  private container: HTMLDivElement | null = null;
  private popupEl: HTMLDivElement | null = null;
  private isVisible: boolean = false;
  private currentAnswerText: string = '';

  constructor() {
    this.initContainer();
    this.attachGlobalListeners();
  }

  private initContainer(): void {
    let existing = document.getElementById('quizlens-root-container') as HTMLDivElement;
    if (!existing) {
      existing = document.createElement('div');
      existing.id = 'quizlens-root-container';
      document.body.appendChild(existing);
    }
    this.container = existing;
  }

  private attachGlobalListeners(): void {
    // Click outside handler
    document.addEventListener('mousedown', (event: MouseEvent) => {
      if (!this.isVisible || !this.popupEl) return;
      const target = event.target as Node;
      if (!this.popupEl.contains(target)) {
        this.hide();
      }
    });

    // Escape key handler
    document.addEventListener('keydown', (event: KeyboardEvent) => {
      if (this.isVisible && event.key === 'Escape') {
        this.hide();
      }
    });
  }

  /**
   * Position the popup relative to the selection rect
   */
  public positionAtRect(rect: DOMRect): void {
    if (!this.popupEl) return;

    const popupWidth = 320;
    const popupEstimatedHeight = 180;
    const margin = 10;

    const pageX = window.scrollX;
    const pageY = window.scrollY;

    // Default: position below the selection
    let top = rect.bottom + pageY + margin;
    let left = rect.left + pageX;

    // Viewport overflow checks
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    // Check if overflowing right
    if (rect.left + popupWidth > viewportWidth - 20) {
      left = Math.max(20, viewportWidth - popupWidth - 20) + pageX;
    }

    // Check if overflowing bottom: if so, position above selection
    if (rect.bottom + popupEstimatedHeight > viewportHeight - 20 && rect.top > popupEstimatedHeight + margin) {
      top = rect.top + pageY - popupEstimatedHeight - margin;
    }

    this.popupEl.style.top = `${Math.round(top)}px`;
    this.popupEl.style.left = `${Math.round(left)}px`;
  }

  /**
   * Ensure popup element exists and is empty
   */
  private preparePopup(rect: DOMRect): void {
    this.initContainer();

    if (!this.popupEl) {
      this.popupEl = document.createElement('div');
      this.popupEl.className = 'quizlens-popup';
      this.container?.appendChild(this.popupEl);
    }

    this.positionAtRect(rect);
    this.popupEl.innerHTML = '';
    this.isVisible = true;
  }

  /**
   * Render Loading State
   */
  public showLoading(rect: DOMRect): void {
    this.preparePopup(rect);
    if (!this.popupEl) return;

    this.popupEl.innerHTML = `
      <div class="quizlens-header">
        <div class="quizlens-brand">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <circle cx="11" cy="11" r="8"></circle>
            <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
          </svg>
          QuizLens AI
        </div>
        <button class="quizlens-close-btn" title="Đóng">&times;</button>
      </div>
      <div class="quizlens-body">
        <div class="quizlens-loading">
          <div class="quizlens-spinner"></div>
          <div class="quizlens-loading-text">AI đang phân tích câu hỏi...</div>
        </div>
      </div>
    `;

    this.bindCloseButton();
  }

  /**
   * Render Success Result State
   */
  public showResult(result: AnswerResult, rect: DOMRect, autoCopy = false): void {
    this.preparePopup(rect);
    if (!this.popupEl) return;

    const qType = result.questionType;
    let sectionLabel = 'ĐÁP ÁN CHÍNH XÁC';
    let typeBadgeHtml = '';

    if (qType === 'MULTI_SELECT') {
      sectionLabel = 'CHỌN NHIỀU ĐÁP ÁN';
      typeBadgeHtml = '<span class="quizlens-type-tag">Chọn nhiều</span>';
    } else if (qType === 'BINARY') {
      sectionLabel = 'CÂU HỎI ĐÚNG / SAI';
      typeBadgeHtml = '<span class="quizlens-type-tag">Đúng/Sai</span>';
    } else if (qType === 'FILL_IN_BLANK') {
      sectionLabel = 'TỪ CẦN ĐIỀN VÀO CHỖ TRỐNG';
      typeBadgeHtml = '<span class="quizlens-type-tag">Điền khuyết</span>';
    } else if (qType === 'SHORT_ANSWER') {
      sectionLabel = 'ĐÁP ÁN NGẮN GỌN';
      typeBadgeHtml = '<span class="quizlens-type-tag">Trả lời nhanh</span>';
    }

    const answerStr = (result.answer || '').trim();
    const isShortBadge = answerStr.length > 0 && answerStr.length <= 6;
    const badgeText = isShortBadge ? answerStr : '✓';

    if (autoCopy && answerStr) {
      const copyVal = isShortBadge && result.answerText ? `${answerStr}. ${result.answerText}` : answerStr || result.answerText || '';
      navigator.clipboard?.writeText(copyVal).catch(() => {});
    }

    this.currentAnswerText = isShortBadge && result.answerText
      ? `${answerStr}. ${result.answerText}`
      : answerStr || result.answerText || '';

    const confidencePercent = Math.round((result.confidence || 0.95) * 100);

    const showExplanation = Boolean(result.answerText && result.answerText.trim() !== answerStr);

    this.popupEl.innerHTML = `
      <div class="quizlens-header">
        <div class="quizlens-brand">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <circle cx="11" cy="11" r="8"></circle>
            <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
          </svg>
          QuizLens AI
          ${typeBadgeHtml}
        </div>
        <button class="quizlens-close-btn" title="Đóng">&times;</button>
      </div>
      <div class="quizlens-body">
        <div class="quizlens-result">
          <div class="quizlens-section-label">${sectionLabel}</div>
          <div class="quizlens-answer-row">
            <div class="quizlens-letter-badge ${isShortBadge ? '' : 'quizlens-badge-icon'}">${badgeText}</div>
            <div class="quizlens-answer-content">
              ${!isShortBadge && answerStr ? `<div class="quizlens-prominent-word">${this.escapeHtml(answerStr)}</div>` : ''}
              ${showExplanation ? `<div class="quizlens-answer-text">${this.escapeHtml(result.answerText!)}</div>` : (isShortBadge && result.answerText ? `<div class="quizlens-answer-text">${this.escapeHtml(result.answerText)}</div>` : '')}
            </div>
          </div>
          <div class="quizlens-meta-bar">
            <span class="quizlens-confidence">Độ tin cậy: ${confidencePercent}%</span>
            <button class="quizlens-copy-btn" id="ql-copy-btn">
              ${autoCopy ? 'Đã sao chép' : 'Sao chép'}
            </button>
          </div>
        </div>
      </div>
    `;

    this.bindCloseButton();
    this.bindCopyButton();
  }

  /**
   * Render UNKNOWN Result State
   */
  public showUnknown(rect: DOMRect, reason?: string): void {
    this.preparePopup(rect);
    if (!this.popupEl) return;

    this.popupEl.innerHTML = `
      <div class="quizlens-header">
        <div class="quizlens-brand">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <circle cx="11" cy="11" r="8"></circle>
            <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
          </svg>
          QuizLens AI
        </div>
        <button class="quizlens-close-btn" title="Đóng">&times;</button>
      </div>
      <div class="quizlens-body">
        <div class="quizlens-unknown">
          <div class="quizlens-unknown-title">Không xác định được câu hỏi</div>
          <div class="quizlens-unknown-desc">
            ${this.escapeHtml(reason || 'Không tìm thấy các phương án lựa chọn (A, B...) xung quanh vùng chọn.')}
          </div>
        </div>
      </div>
    `;

    this.bindCloseButton();
  }

  /**
   * Render Error State
   */
  public showError(message: string, rect: DOMRect): void {
    this.preparePopup(rect);
    if (!this.popupEl) return;

    this.popupEl.innerHTML = `
      <div class="quizlens-header">
        <div class="quizlens-brand">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <circle cx="11" cy="11" r="8"></circle>
            <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
          </svg>
          QuizLens AI
        </div>
        <button class="quizlens-close-btn" title="Đóng">&times;</button>
      </div>
      <div class="quizlens-body">
        <div class="quizlens-error">
          <div class="quizlens-unknown-title" style="color: var(--ql-error)">Lỗi xử lý</div>
          <div class="quizlens-error-desc">${this.escapeHtml(message)}</div>
        </div>
      </div>
    `;

    this.bindCloseButton();
  }

  public hide(): void {
    if (this.popupEl && this.container) {
      this.popupEl.remove();
      this.popupEl = null;
    }
    this.isVisible = false;
  }

  private bindCloseButton(): void {
    const btn = this.popupEl?.querySelector('.quizlens-close-btn');
    btn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.hide();
    });
  }

  private bindCopyButton(): void {
    const btn = this.popupEl?.querySelector('#ql-copy-btn') as HTMLButtonElement | null;
    if (!btn) return;

    btn.addEventListener('click', async (e) => {
      e.stopPropagation();
      try {
        await navigator.clipboard.writeText(this.currentAnswerText);
        btn.textContent = 'Đã sao chép!';
        btn.classList.add('copied');
        setTimeout(() => {
          if (btn) {
            btn.textContent = 'Sao chép';
            btn.classList.remove('copied');
          }
        }, 2000);
      } catch (err) {
        btn.textContent = 'Lỗi copy';
      }
    });
  }

  private escapeHtml(str: string): string {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }
}

